"""Raft consensus protocol node."""

from typing import List, Optional
from log_entry import LogEntry
from rpc import RequestVoteArgs, RequestVoteReply


class RaftNode:
    def __init__(self, node_id: str):
        self.node_id = node_id
        self.current_term = 0
        self.voted_for: Optional[str] = None
        self.log: List[LogEntry] = []

    @property
    def last_log_index(self) -> int:
        return self.log[-1].index if self.log else 0

    @property
    def last_log_term(self) -> int:
        return self.log[-1].term if self.log else 0

    def handle_request_vote(self, args: RequestVoteArgs) -> RequestVoteReply:
        if args.term < self.current_term:
            return RequestVoteReply(self.current_term, False)

        if args.term > self.current_term:
            self.current_term = args.term
            self.voted_for = None

        # BUG: Only checks if voted_for is None or equals candidate_id,
        # completely ignoring §5.4.1 log up-to-dateness check!
        # Allows stale candidate with shorter/older log to receive votes.
        can_vote = self.voted_for is None or self.voted_for == args.candidate_id
        if can_vote:
            self.voted_for = args.candidate_id
            return RequestVoteReply(self.current_term, True)
        return RequestVoteReply(self.current_term, False)

